static NSString *PVXSourceHash(NSDictionary *row){NSString *url=[row[@"url"] isKindOfClass:NSString.class]?row[@"url"]:@"";if(!url.length)return nil;NSString *text=[NSString stringWithFormat:@"%@\n%@",row[@"kind"]?:@"video",url];NSData *d=[text dataUsingEncoding:NSUTF8StringEncoding];unsigned char hash[CC_SHA256_DIGEST_LENGTH];CC_SHA256(d.bytes,(CC_LONG)d.length,hash);NSMutableString *s=[NSMutableString string];for(unsigned i=0;i<sizeof hash;i++)[s appendFormat:@"%02x",hash[i]];return s;}
void PVXRememberSource(NSDictionary *candidate,NSDictionary *receipt){NSString *hash=PVXSourceHash(candidate);if(!hash||![receipt[@"id"] isKindOfClass:NSString.class])return;NSString *dir=[PVXStateRoot() stringByAppendingPathComponent:@"plus-source-links"];[NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:nil];NSDictionary *value=@{@"id":receipt[@"id"],@"kind":candidate[@"kind"]?:@"video"};NSData *data=[NSPropertyListSerialization dataWithPropertyList:value format:NSPropertyListBinaryFormat_v1_0 options:0 error:nil];[data writeToFile:[[dir stringByAppendingPathComponent:hash] stringByAppendingPathExtension:@"plist"] options:NSDataWritingAtomic error:nil];}
NSDictionary *PVXLinkedTask(NSDictionary *candidate,NSArray<NSDictionary*> *tasks){NSString *hash=PVXSourceHash(candidate);if(!hash)return nil;NSString *path=[[[PVXStateRoot() stringByAppendingPathComponent:@"plus-source-links"] stringByAppendingPathComponent:hash] stringByAppendingPathExtension:@"plist"];NSDictionary *link=[NSDictionary dictionaryWithContentsOfFile:path];NSString *uuid=link[@"id"];for(NSDictionary *task in tasks)if([task[@"id"] isEqual:uuid]&&[task[@"kind"] isEqual:candidate[@"kind"]])return task;return nil;}
static NSString *PVXCodecName(AVAssetTrack *track){if(!track)return @"编码未知";NSArray *formats=track.formatDescriptions;if(!formats.count)return @"编码未知";CMFormatDescriptionRef d=(__bridge CMFormatDescriptionRef)formats.firstObject;FourCharCode c=CMFormatDescriptionGetMediaSubType(d);switch(c){case kCMVideoCodecType_H264:return @"H.264";case kCMVideoCodecType_HEVC:return @"HEVC";case kCMVideoCodecType_VP9:return @"VP9";case kCMVideoCodecType_AV1:return @"AV1";default:return [NSString stringWithFormat:@"编码 %c%c%c%c",(int)((c>>24)&255),(int)((c>>16)&255),(int)((c>>8)&255),(int)(c&255)];}}
static NSString *PVXQualityText(BOOL image,CGFloat width,CGFloat height,NSString *codec){NSInteger w=lround(fabs(width)),h=lround(fabs(height));if(w<=0||h<=0)return @"分辨率未知";if(image)return [NSString stringWithFormat:@"%ld×%ld",(long)w,(long)h];NSInteger shortSide=MIN(w,h),longSide=MAX(w,h);NSString *name=shortSide>=4320&&longSide>=7680?@"8K":shortSide>=2160&&longSide>=3840?@"4K":[NSString stringWithFormat:@"%ldp",(long)shortSide];return [NSString stringWithFormat:@"%@ · %ld×%ld%@",name,(long)w,(long)h,codec.length?[NSString stringWithFormat:@" · %@",codec]:@""];}
void PVXFetchMediaQuality(NSDictionary *row,void(^done)(NSString*)){NSString *local=PVXTaskLocalPath(row);BOOL image=[row[@"kind"] isEqual:@"image"];if(!local){CGFloat w=[row[@"width"] doubleValue],h=[row[@"height"] doubleValue];NSString *text=(w>0&&h>0)?PVXQualityText(image,w,h,nil):(!image&&h>0?[NSString stringWithFormat:@"%ldp",(long)lround(h)]:@"分辨率未知");done(text);return;}static NSCache *cache;static NSMutableDictionary *waiting;if(!cache){cache=[NSCache new];cache.countLimit=256;waiting=[NSMutableDictionary dictionary];}NSString *key=[NSString stringWithFormat:@"%@:%@",row[@"id"],local];NSString *cached=[cache objectForKey:key];if(cached){done(cached);return;}if(waiting[key]){[waiting[key] addObject:[done copy]];return;}waiting[key]=[NSMutableArray arrayWithObject:[done copy]];dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{CGFloat w=0,h=0;NSString *codec=nil;if(image){CGImageSourceRef src=CGImageSourceCreateWithURL((__bridge CFURLRef)[NSURL fileURLWithPath:local],(__bridge CFDictionaryRef)@{(__bridge NSString*)kCGImageSourceShouldCache:@NO});if(src){NSDictionary *props=CFBridgingRelease(CGImageSourceCopyPropertiesAtIndex(src,0,NULL));w=[props[(__bridge NSString*)kCGImagePropertyPixelWidth] doubleValue];h=[props[(__bridge NSString*)kCGImagePropertyPixelHeight] doubleValue];CFRelease(src);}}else{AVURLAsset *asset=[AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:local] options:nil];AVAssetTrack *track=[asset tracksWithMediaType:AVMediaTypeVideo].firstObject;if(track){CGSize size=CGSizeApplyAffineTransform(track.naturalSize,track.preferredTransform);w=fabs(size.width);h=fabs(size.height);codec=PVXCodecName(track);}}NSString *quality=PVXQualityText(image,w,h,codec);dispatch_async(dispatch_get_main_queue(),^{[cache setObject:quality forKey:key];NSArray *callbacks=waiting[key];[waiting removeObjectForKey:key];for(void(^block)(NSString*) in callbacks)block(quality);});});}
